#!/usr/bin/env python3
from pathlib import Path
import json,gzip,copy
P=Path(__file__).resolve().parent;C=P.parent/'contexts'
with gzip.open(P/'source-objects.geojson.gz','rt',encoding='utf-8') as h:objects={f['id']:f for f in json.load(h)['features']}
r=json.load(open(P/'recipes.json'));tasks=json.load(open(P/'assignment.json'))['municipalities'];city={c['municipality']:c for c in tasks}
def get(c,kind,pred):
 k=city[c]['contextKey'];fs=json.load(gzip.open(C/k/(kind+'.geojson.gz'),'rt'));out=[]
 for f in fs['features']:
  if not pred(f):continue
  f=copy.deepcopy(f);f['properties']['originalId']=f['id'];f['id']=k+':'+kind+':'+f['id'];objects[f['id']]=f;out.append(f['id'])
 if not out:raise ValueError((c,kind,'none'))
 return out
def area(c,ids):return get(c,'areas',lambda f:f['id'] in ['osm:way:'+str(i) for i in ids])
def roads(c,n):return get(c,'roads',lambda f:f['properties']['name'] in n)
def add(c,n,ids,url,note,ev,op='union',partial=False,allow=0):
 if any(x['municipality']==c and x['name']==n for x in r):return
 r.append(dict(municipality=c,name=n,operation=op,inputIds=ids,sourceUrl=url,supportingUrls=list(dict.fromkeys(objects[i]['properties']['source']['url'] for i in ids)),evidenceFiles=['evidence/'+ev],partialFootprint=partial,frontageAllowanceM=allow,approximationNote=note))
zurl='https://avlzalazone.com/teszteles-es-palyak/'
add('Zalaegerszeg','ADAS platform',area('Zalaegerszeg',[647858231]),zurl,'Original asphalt area-way contains the saved ADAS name and lies in the separate ZalaZONE module described by the operator. This preserves the mapped full surface outline, not the whole parent test facility. The source area itself is unnamed, so its identity with the label and the full module extremities remain an explicit low-confidence inference. Any adjacent run-off/technical grounds outside the asphalt are unresolved.','first-primary-search.json',partial=True)
add('Zalaegerszeg','Dinamikai felület',area('Zalaegerszeg',[647858280]),'https://www.avlzalazone.com/testing-and-track/dynamics-platform/','Original source area-way is explicitly named Dinamikai felület and includes its circular dynamic asphalt surface and long acceleration strip. The operator describes that physical layout. The asphalt footprint is preserved directly; it is not a circle manufactured around a label. Wider facility safety/operating perimeter remains uncertain.','first-primary-search.json',partial=True)
add('Zalaegerszeg','Kezelhetőségi pálya',roads('Zalaegerszeg',['Kezelhetőségi pálya']),'https://avlzalazone.com/teszteles-es-palyak/kezelhetosegi-palya/','The actual source road circuits named Kezelhetőségi pálya define the spatial extent of this separately operator-described test module. Their convex envelope includes the intervening test-course grounds, with an inferred 20 m external verge/run-off allowance. It is a whole-module estimate, not the larger ZalaZONE parent or a point ring. Track cut-ins, safety margins and exact module boundary remain uncertain.','first-primary-search.json','street-envelope',False,20)
add('Fertőd','Tőzeggyármajor',area('Fertőd',[757107372]),'https://www.fertod.hu/hu/projektek/15','The municipality separately identifies Tőzeggyármajor as a settlement part. This preserves the native complete residential landuse outline of its detached street grid, next to the archived label. The 17 m label offset is retained honestly; the point is not used to enlarge the source ring. Agricultural/industrial outer territory of the historic locality is not established.','remaining-west-localities.json',partial=True)
add('Sárvár','Ipartelep',area('Sárvár',[228357079])+roads('Sárvár',['Ipartelep utca']),'https://njt.jog.gov.hu/jogszabaly/2013-3-SP-5Y3245','Municipal records identify Ipartelep street and facilities. The actual large industrial landuse parcel plus its named Ipartelep street form a coarse whole industrial-quarter envelope. The convex outer joins infer how the street-front plots relate to the industrial compound; legal and historical extremities are not published by this evidence.','rural-west-search.json','convex-envelope',False,20)
add('Vitnyéd','Csermajor',area('Vitnyéd',[920980559]),'https://www.mavcsoport.hu/mavinform/helykozi-autobusz-menetrendi-valtozas-szeptember-1-jetol','The official transit source names Vitnyéd-Csermajor. This preserves the entire original farmyard compound containing the Csermajor label and its local institutional/farm settlement. It is a meaningful occupied-core footprint; wider former estate fields are unresolved.','west-localities-search.json',partial=True)
add('Celldömölk','Sághegy',area('Celldömölk',[1574172754]),'https://celldomolk.hu/latnivalok/','Municipal descriptions identify the Ság hill and its vineyard landscape. This uses the native large Sághegyi Tájvédelmi Körzet outline as a rough whole-hill landscape extent. Protected-landscape and locality identities are related spatial contexts, not asserted identical legal units; the settlement/vineyard quarter may extend differently. It is explicitly a partial source-footprint estimate of that locality, not just the crater or visitor building.','rural-west-search.json',partial=True)
add('Újrónafő','Császárrét',area('Újrónafő',[579956634,579956633,579956632]),'https://ujronafo.hu/ujronafo-tortenete/','The municipality describes Császárrét as its separate former estate settlement about 1 km from the village centre. The original complete farmyard and both residential surface polygons form the occupied whole settlement core. Open gaps and native geometry are preserved; the wider historic estate boundary is unresolved.','remaining-west-localities.json',partial=True)
add('Győr','Malomsziget',area('Győr',[426272088]),'https://www.openstreetmap.org/way/426272088','The original native grassland polygon is itself named Malomsziget and contains the independently retained Malomsziget place label. Its full irregular physical meadow/island outline is preserved. This is a directly name-matched source landscape footprint; any broader historical neighborhood usage is unresolved.','gyor-cserszeg-street-lists.json',partial=True)
add('Szőlősgyörök','Páskom',area('Szőlősgyörök',[1259780865,1259780878]),'https://szolosgyorok.hu/images/dokumentumok/kozlemenyek/szallashely_nyilvantartas_2024.pdf','Municipal address records and a local producer identify Páskom hegy as the vineyard/cellar locality. The native vineyard parcel containing its label and the adjacent mapped allotment/cellar area provide a meaningful occupied-hillside footprint. The union preserves original parcel edges and does not purport to cover every vineyard of the larger hill.','south-localities-search.json',partial=True)
add('Kutas','Kozmapuszta',area('Kutas',[666120339]),'https://www.hertelendy-castle.com/wp-content/uploads/KUTAS_TELEPuLeSRENDEZeSI_ESZKoZoK_3._SZ._MoDOSiTaS__JSZ_202017.pdf','The local planning document names Kutas-Kozmapuszta and its estate context. The entire original Hertelendy castle/estate park landuse footprint containing the named locality is retained. This is an occupied estate-core partial footprint, not just a building; the wider rural locality and separate farm housing may extend beyond it.','balaton-rural-search.json',partial=True)
add('Balatonszárszó','Nagyasszonyi-erdő',area('Balatonszárszó',[1096983647]),'https://www.openstreetmap.org/node/1264773899','The original Nagyasszonyi-erdő woodland-place label falls inside this complete mapped woodland surface. Its irregular forest boundaries provide a rough physical forest-locality extent, not a point-derived buffer. The area-way is unnamed and may include adjoining woods, so the correspondence and historical forest extremities are explicitly low confidence.','eastern-shard-search.json',partial=True)
(P/'recipes.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n')
raw=json.dumps(dict(type='FeatureCollection',features=list(objects.values())),ensure_ascii=False,separators=(',',':')).encode();(P/'source-objects.geojson.gz').write_bytes(gzip.compress(raw,mtime=0))
print(len(r),'recipes',len(objects),'objects')
